import sys, re, json

def parse_srt(path):
    txt = open(path, encoding="utf-8").read().replace("\r\n","\n")
    blocks = [b for b in txt.strip().split("\n\n") if b.strip()]
    cues=[]
    for b in blocks:
        lines=b.split("\n")
        idx=int(lines[0])
        m=re.match(r"(\d\d):(\d\d):(\d\d),(\d\d\d) --> (\d\d):(\d\d):(\d\d),(\d\d\d)", lines[1])
        g=[int(x) for x in m.groups()]
        inn=g[0]*3600+g[1]*60+g[2]+g[3]/1000.0
        out=g[4]*3600+g[5]*60+g[6]+g[7]/1000.0
        text="\n".join(lines[2:])
        cues.append({"idx":idx,"in":inn,"out":out,"text":text})
    return cues

def count_chars(s):
    # T1: hanzi, fullwidth punct, letters, digits count 1; halfwidth space not counted
    return len([c for c in s if c != " "])

for path in sys.argv[1:]:
    print("=====", path)
    cues=parse_srt(path)
    for c in cues:
        lines=c["text"].split("\n")
        dur=c["out"]-c["in"]
        total=count_chars(c["text"].replace("\n",""))
        cps=total/dur if dur>0 else 0
        flags=[]
        if len(lines)>2: flags.append("T2>2lines")
        for L in lines:
            if count_chars(L)>16: flags.append(f"T1 len{count_chars(L)}:{L}")
            if L.rstrip().endswith(("，","。",",",".")): flags.append(f"T4 lineend:{L}")
        if cps>9: flags.append(f"T3 {cps:.2f}")
        if "..." in c["text"] or "。。。" in c["text"]: flags.append("T4 dots")
        if re.search(r"[A-Za-z0-9]\s?,\s?", c["text"]): flags.append("halfwidth comma?")
        # single ellipsis char count
        if c["text"].count("…")%2==1: flags.append("T4 odd-ellipsis")
        if re.search(r"[,!?:;]", c["text"]): flags.append("halfwidth punct")
        print(f"cue{c['idx']:>2} {c['in']:8.3f}-{c['out']:8.3f} dur{dur:6.3f} chars{total:3d} cps{cps:5.2f} lines{len(lines)} {flags} | {c['text']!r}")
    # gaps
    for a,b in zip(cues, cues[1:]):
        gap_frames=round((b["in"]-a["out"])*24,2)
        if "{\\an8}" in b["text"] or "{\\an8}" in a["text"]:
            tag="FN"
        else:
            tag=""
        print(f"  gap cue{a['idx']}->cue{b['idx']}: {gap_frames} frames {tag}")

